WITH base AS (SELECT *, CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END AS is_singapore FROM suppliers WHERE supplier_name IS NOT NULL), Summary AS (SELECT country, city, MAX(is_singapore) AS max_is_singapore, AVG(is_singapore) AS avg_is_singapore FROM base GROUP BY country, city) SELECT country, city, max_is_singapore, avg_is_singapore FROM Summary WHERE avg_is_singapore > 62 ORDER BY max_is_singapore DESC;
